import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let fertiliser=p[0]===1;g.box(0,.45,0,1.2,.5,.7,'#c4a375');for(let i=0;i<30;i++){let x=Math.sin(i*7)*1.1,y=.2+Math.cos(i*3)*.3,z=Math.sin(i*5)*.6;g.sphere(x,y,z,fertiliser?.04:.08,fertiliser?C.blue:C.gold)}g.line([0,-.9,0],[0,-.1,0],C.green,4);g.sphere(-.15,-.7,0,.12,C.green);g.sphere(.15,-.5,0,.12,C.green);return[{label:b('Input','पोषण स्रोत'),value:fertiliser?b('Fertiliser','उर्वरक'):b('Manure','खाद')},{label:b('Main benefit','मुख्य लाभ'),value:fertiliser?b('Concentrated specific nutrients','विशिष्ट पोषक अधिक सान्द्र रूप में'):b('Organic matter and soil structure','जैविक पदार्थ और मिट्टी संरचना')}];};
